        Dhikr("اللَّهُمَّ رَبَّ هَذِهِ الدَّعْوَةِ التَّامَّةِ، وَالصَّلَاةِ الْقَائِمَةِ، آتِ مُحَمَّدًا الْوَسِيلَةَ وَالْفَضِيلَةَ، وَابْعَثْهُ مَقَامًا مَحْمُودًا الَّذِي وَعَدْتَهُ",1,"بعد الأذان · البخاري"),
        Dhikr("اللَّهُمَّ اجْعَلْ فِي قَلْبِي نُورًا، وَفِي لِسَانِي نُورًا، وَفِي سَمْعِي نُورًا، وَفِي بَصَرِي نُورًا، وَمِنْ فَوْقِي نُورًا، وَمِنْ تَحْتِي نُورًا، وَعَنْ يَمِينِي نُورًا، وَعَنْ شِمَالِي نُورًا، وَمِنْ أَمَامِي نُورًا، وَمِنْ خَلْفِي نُورًا، وَاجْعَلْ فِي نَفْسِي نُورًا، وَأَعْظِمْ لِي نُورًا",1,"الذهاب إلى المسجد · البخاري ومسلم"),
        Dhikr("أَعُوذُ بِاللَّهِ الْعَظِيمِ، وَبِوَجْهِهِ الْكَرِيمِ، وَسُلْطَانِهِ الْقَدِيمِ، مِنَ الشَّيْطَانِ الرَّجِيمِ",1,"عند دخول المسجد · أبو داود"),
        Dhikr("بِسْمِ اللَّهِ، وَالصَّلَاةُ وَالسَّلَامُ عَلَى رَسُولِ اللَّهِ، اللَّهُمَّ افْتَحْ لِي أَبْوَابَ رَحْمَتِكَ",1,"عند دخول المسجد · مسلم"),
        Dhikr("بِسْمِ اللَّهِ، وَالصَّلَاةُ وَالسَّلَامُ عَلَى رَسُولِ اللَّهِ، اللَّهُمَّ إِنِّي أَسْأَلُكَ مِنْ فَضْلِكَ",1,"عند الخروج من المسجد · مسلم"),
    )

    /** One dua a day on the home screen: Quranic duas and short prophetic ones. */
    val daily=listOf(
        Dhikr("رَبَّنَا آتِنَا فِي الدُّنْيَا حَسَنَةً وَفِي الْآخِرَةِ حَسَنَةً وَقِنَا عَذَابَ النَّارِ",1,"البقرة ٢٠١"),
        Dhikr("رَبِّ اشْرَحْ لِي صَدْرِي ﴿٢٥﴾ وَيَسِّرْ لِي أَمْرِي ﴿٢٦﴾",1,"طه ٢٥–٢٦"),
        Dhikr("رَّبِّ زِدْنِي عِلْمًا",1,"طه ١١٤"),
        Dhikr("رَبَّنَا لَا تُزِغْ قُلُوبَنَا بَعْدَ إِذْ هَدَيْتَنَا وَهَبْ لَنَا مِن لَّدُنكَ رَحْمَةً ۚ إِنَّكَ أَنتَ الْوَهَّابُ",1,"آل عمران ٨"),
        Dhikr("رَبِّ اجْعَلْنِي مُقِيمَ الصَّلَاةِ وَمِن ذُرِّيَّتِي ۚ رَبَّنَا وَتَقَبَّلْ دُعَاءِ",1,"إبراهيم ٤٠"),
        Dhikr("رَبَّنَا هَبْ لَنَا مِنْ أَزْوَاجِنَا وَذُرِّيَّاتِنَا قُرَّةَ أَعْيُنٍ وَاجْعَلْنَا لِلْمُتَّقِينَ إِمَامًا",1,"الفرقان ٧٤"),
        Dhikr("لَّا إِلَٰهَ إِلَّا أَنتَ سُبْحَانَكَ إِنِّي كُنتُ مِنَ الظَّالِمِينَ",1,"الأنبياء ٨٧"),
        Dhikr("رَبَّنَا ظَلَمْنَا أَنفُسَنَا وَإِن لَّمْ تَغْفِرْ لَنَا وَتَرْحَمْنَا لَنَكُونَنَّ مِنَ الْخَاسِرِينَ",1,"الأعراف ٢٣"),
        Dhikr("رَبِّ إِنِّي لِمَا أَنزَلْتَ إِلَيَّ مِنْ خَيْرٍ فَقِيرٌ",1,"القصص ٢٤"),
        Dhikr("رَبَّنَا اغْفِرْ لِي وَلِوَالِدَيَّ وَلِلْمُؤْمِنِينَ يَوْمَ يَقُومُ الْحِسَابُ",1,"إبراهيم ٤١"),
        Dhikr("رَّبِّ ارْحَمْهُمَا كَمَا رَبَّيَانِي صَغِيرًا",1,"الإسراء ٢٤"),
        Dhikr("حَسْبُنَا اللَّهُ وَنِعْمَ الْوَكِيلُ",1,"آل عمران ١٧٣"),
        Dhikr("اللَّهُمَّ إِنِّي أَسْأَلُكَ الْعَفْوَ وَالْعَافِيَةَ فِي الدُّنْيَا وَالْآخِرَةِ",1,"أبو داود وابن ماجه"),
        Dhikr("يَا مُقَلِّبَ الْقُلُوبِ ثَبِّتْ قَلْبِي عَلَى دِينِكَ",1,"الترمذي"),
        Dhikr("اللَّهُمَّ أَعِنِّي عَلَى ذِكْرِكَ وَشُكْرِكَ وَحُسْنِ عِبَادَتِكَ",1,"أبو داود والنسائي"),
    )
    fun duaOfDay(date: java.time.LocalDate)=daily[Math.floorMod(date.toEpochDay(),daily.size.toLong()).toInt()]

    /** For the worship companion: identifies the texts that its evidence rules refer to. */
    val KURSI_TEXT get()=KURSI
    val MUAWWIDHAT_TEXTS get()=setOf(IKHLAS,FALAQ,NAS)
    /** The four after-prayer items that make the hundred: 33 tasbih, 33 tahmid, 33 takbir and the closing tahlil. */
    fun isAfterPrayerHundred(d: Dhikr)=(d.count==33 && d.text in setOf("سُبْحَانَ اللَّهِ","الْحَمْدُ لِلَّهِ","اللَّهُ أَكْبَرُ")) || d.source.startsWith("تمام المائة")

    /** Phrases offered by the tasbeeh counter. */
    val tasbeeh=listOf("سُبْحَانَ اللَّهِ","الْحَمْدُ لِلَّهِ","اللَّهُ أَكْبَرُ","لَا إِلَهَ إِلَّا اللَّهُ","أَسْتَغْفِرُ اللَّهَ","سُبْحَانَ اللَّهِ وَبِحَمْدِهِ","اللَّهُمَّ صَلِّ عَلَى مُحَمَّدٍ")
}
